                                                inplace=True)
        if self.has_forces:
            self.convert_forces_from_native(ts._forces, inplace=True)
        if self.periodic:
            # in-place ! (only lengths)
            self.convert_pos_from_native(ts.dimensions[:3])
    ts.frame = frame  # frame labels are 0-based
    self._current_frame = frame
    return ts

