             positions=has_positions,
             velocities=has_velocities,
             forces=has_forces,
             **kwargs)
    if has_positions:
        ts.positions = positions
    if has_velocities:
        ts.velocities = velocities
    if has_forces:
        ts.forces = forces

    return ts

